package r006
import ("context"; "errors"; "log/slog"; "net/http"; "net/http/httptest"; "testing"; httpadapter "github.com/example/alert-orchestration-engine/internal/adapter/http"; "github.com/example/alert-orchestration-engine/internal/domain/notification"; "github.com/example/alert-orchestration-engine/internal/infrastructure/notifier")
func TestR006Recover(t *testing.T){rr:=httptest.NewRecorder();h:=httpadapter.Recover(slog.Default(),http.HandlerFunc(func(http.ResponseWriter,*http.Request){panic("x")}));h.ServeHTTP(rr,httptest.NewRequest(http.MethodGet,"/",nil));if rr.Code!=500{t.Fatal(rr.Code)}}
func TestR006Cors(t *testing.T){called:=false;h:=httpadapter.CORS(http.HandlerFunc(func(http.ResponseWriter,*http.Request){called=true}));h.ServeHTTP(httptest.NewRecorder(),httptest.NewRequest(http.MethodOptions,"/",nil));if called{t.Fatal("preflight continued")}}
func TestR006Auth(t *testing.T){got:="";h:=httpadapter.AuthPlaceholder(http.HandlerFunc(func(_ http.ResponseWriter,r *http.Request){got=httpadapter.Subject(r.Context())}));r:=httptest.NewRequest(http.MethodGet,"/",nil);r.Header.Set("X-Caller-Subject","op");h.ServeHTTP(httptest.NewRecorder(),r);if got!="op"{t.Fatal(got)}}
func TestR006Webhook(t *testing.T){ctx,c:=context.WithCancel(context.Background());c();if !errors.Is((notifier.WebhookSigner{Secret:[]byte("s")}).Send(ctx,notification.Record{Target:"https://x"}),context.Canceled){t.Fatal("cancel ignored")}}
